# Find all unique 3x3 blocks and their properties
def extract_3x3_blocks(grid, start_row, start_col):
    """Extract 3x3 block starting at (start_row, start_col)"""
    if start_row + 3 > len(grid) or start_col + 3 > len(grid[0]):
        return None
    block = []
    for r in range(3):
        row = grid[start_row + r][start_col:start_col + 3]
        block.append(row)
    return block

# Print all 3x3 blocks in the grid
print("All 3x3 blocks:")
for r in range(len(grid) - 2):
    for c in range(len(grid[0]) - 2):
        block = extract_3x3_blocks(grid, r, c)
        colors = set()
        for row in block:
            colors.update(row)
        print(f"({r},{c}): {block} | colors: {sorted(colors)}")

